-- IPA 2020-12-13 FE exemption examination, Q44, Q45 and Q48.
-- Source-attributed adaptations. Additive only; retain existing learning records.
INSERT OR IGNORE INTO questions (id,track_id,topic,difficulty,question_type,prompt,options_json,answer_json,explanation,source_type,source_reference,language,exam_section,exam_section_method,question_kind,exam_origin) VALUES
('fe-exempt-2020-20201213-q44','exam-fe','SEOポイズニング','standard','single_choice','【IPA 2020年度 修了認定試験 2020-12-13 問44・改編】検索結果の上位に悪意あるサイトを表示させる攻撃はどれか。','[{"id":"a","text":"DNSキャッシュポイズニング"},{"id":"b","text":"SEOポイズニング"},{"id":"c","text":"クロスサイトスクリプティング"},{"id":"d","text":"ソーシャルエンジニアリング"}]','"b"','検索順位を操作し、悪意あるサイトへ誘導する手口はSEOポイズニングである。DNSキャッシュポイズニングは名前解決情報を偽装する攻撃。\n\n中文解析：SEO投毒通过操纵搜索排名引导用户进入恶意网站；DNS缓存投毒则是伪造域名解析信息。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20201213_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2020-20201213-q45','exam-fe','フールプルーフ','standard','single_choice','【IPA 2020年度 修了認定試験 2020-12-13 問45・改編】安全性・信頼性を確保する設計のうち、フールプルーフに該当するものはどれか。','[{"id":"a","text":"故障時にシステムを安全に停止して被害を最小限に抑える"},{"id":"b","text":"故障時に機能や処理能力を制限しながら稼働を続ける"},{"id":"c","text":"二重化などの冗長構成で故障の影響を防ぐ"},{"id":"d","text":"利用者が誤操作してもシステムに異常が起こらないようにする"}]','"d"','フールプルーフは人の誤操作が異常につながらないよう設計する考え方。安全停止はフェールセーフ、機能を落として運転継続するのはフェールソフトである。\n\n中文解析：防呆设计使用户误操作不致造成系统异常；安全停止属于故障安全，降低功能继续运行属于故障软化。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20201213_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2020-20201213-q48','exam-fe','スタブ・ドライバ','standard','single_choice','【IPA 2020年度 修了認定試験 2020-12-13 問48・改編】テストに用いるスタブとドライバの説明として適切なものはどれか。','[{"id":"a","text":"スタブはテスト対象モジュールの戻り値を表示・印刷する"},{"id":"b","text":"スタブはテスト対象モジュールを呼び出す"},{"id":"c","text":"ドライバはテスト対象モジュールから呼び出される"},{"id":"d","text":"ドライバは引数を渡してテスト対象モジュールを呼び出す"}]','"d"','ドライバはテスト対象を呼び出す側を代行し、スタブはテスト対象から呼び出される側を代行する。\n\n中文解析：驱动程序代替调用方，向被测模块传递参数；桩程序代替被测模块调用的下层模块。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20201213_FE.pdf','ja','A','explicit','standard','fe_exemption');
